package com.travbook.stays.adapter.out.persistence;
import com.travbook.stays.application.port.out.StayStore;
import com.travbook.stays.application.port.in.HotelStays.*;
import com.travbook.stays.domain.model.Stay.*;
import com.travbook.shared.domain.DomainFailure;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import static com.travbook.shared.domain.DomainFailure.Code.*;
public final class JdbcStayStore implements StayStore {
 private final JdbcClient jdbc;private final TransactionTemplate tx;private final ObjectMapper json;private final Clock clock;
 public JdbcStayStore(JdbcClient jdbc,TransactionTemplate tx,ObjectMapper json,Clock clock){this.jdbc=jdbc;this.tx=tx;this.json=json;this.clock=clock;}
 private Booking readBooking(String value){var node=(tools.jackson.databind.node.ObjectNode)json.readTree(value);if(!node.has("changes"))node.putArray("changes");if(!node.has("amendments"))node.putArray("amendments");return json.treeToValue(node,Booking.class);}
 private void lockWork(UUID owner,UUID id){jdbc.sql("select w.booking_id from stay_work w join stay_booking b on b.id=w.booking_id where b.id=:id and b.customer_id=:owner for update of w").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);}
 private void useQuote(UUID quote,UUID booking){if(jdbc.sql("insert into stay_quote_use(quote_id,booking_id) values(:quote,:booking) on conflict(quote_id) do nothing").param("quote",quote).param("booking",booking).update()!=1)throw new DomainFailure(BOOKING_CONFLICT,"This quote was already used for a booking or amendment.");}
 private String fingerprint(String input){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private DomainFailure missing(){return new DomainFailure(NOT_FOUND,"Hotel resource not found.");}
 public Optional<UUID> replay(UUID owner,String operation,String key,String fingerprint){return jdbc.sql("select fingerprint,resource_id from stay_command where customer_id=:owner and operation=:op and command_key=:key").param("owner",owner).param("op",operation).param("key",key).query((r,n)->{if(!r.getString(1).equals(fingerprint))throw new DomainFailure(IDEMPOTENCY_CONFLICT,"This key was used for different hotel inputs.");return r.getObject(2,UUID.class);}).optional();}
 private boolean claim(UUID owner,String operation,String key,String fingerprint,UUID resource,UUID command){return jdbc.sql("insert into stay_command(id,customer_id,operation,command_key,fingerprint,resource_id) values(:id,:owner,:op,:key,:fingerprint,:resource) on conflict(customer_id,operation,command_key) do nothing").param("id",command).param("owner",owner).param("op",operation).param("key",key).param("fingerprint",fingerprint).param("resource",resource).update()==1;}
 private Quote ownedQuote(UUID owner,UUID id){return jdbc.sql("select payload::text from stay_quote where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(s->json.readValue(s,Quote.class)).orElseThrow(this::missing);}
 public QuoteDetails quote(UUID owner,UUID id){var q=ownedQuote(owner,id);Instant accepted=jdbc.sql("select accepted_at from stay_acceptance where quote_id=:id").param("id",id).query((r,n)->r.getTimestamp(1).toInstant()).optional().orElse(null);UUID booking=jdbc.sql("select u.booking_id from stay_quote_use u join stay_booking b on b.id=u.booking_id where u.quote_id=:id and b.customer_id=:owner").param("id",id).param("owner",owner).query(UUID.class).optional().orElseGet(()->jdbc.sql("select booking_id from stay_change_quote where quote_id=:id").param("id",id).query(UUID.class).optional().orElse(null));return new QuoteDetails(q,accepted,booking,q.expired(clock.instant()));}
 public Quote createQuote(Quote q,String key,String fingerprint,UUID correlation){return tx.execute(t->{UUID command=UUID.randomUUID();if(!claim(q.owner(),"QUOTE",key,fingerprint,q.id(),command))return ownedQuote(q.owner(),replay(q.owner(),"QUOTE",key,fingerprint).orElseThrow());q.valid(clock.instant());jdbc.sql("insert into stay_quote(id,customer_id,created_at,expires_at,payload) values(:id,:owner,:created,:expires,cast(:payload as jsonb))").param("id",q.id()).param("owner",q.owner()).param("created",Timestamp.from(q.createdAt())).param("expires",Timestamp.from(q.expiresAt())).param("payload",json.writeValueAsString(q)).update();event(q.id(),1,"HotelQuoteCreated",command,correlation,"CREATED","N/A","N/A","N/A");return q;});}
 public void accept(UUID owner,UUID id,int version,String key,String fingerprint,UUID correlation){tx.executeWithoutResult(t->{UUID command=UUID.randomUUID();if(!claim(owner,"ACCEPT",key,fingerprint,id,command)){replay(owner,"ACCEPT",key,fingerprint).orElseThrow();return;}jdbc.sql("select id from stay_quote where id=:id and customer_id=:owner for update").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);var q=ownedQuote(owner,id);if(version!=q.version())throw new DomainFailure(QUOTE_VERSION_CONFLICT,"Accept the exact hotel quote version.");q.valid(clock.instant());if(jdbc.sql("insert into stay_acceptance(quote_id,accepted_at,version) values(:id,:now,1) on conflict(quote_id) do nothing").param("id",id).param("now",Timestamp.from(clock.instant())).update()==1)event(id,2,"HotelQuoteAccepted",command,correlation,"ACCEPTED","N/A","N/A","N/A");});}
 public Booking createBooking(UUID owner,UUID quoteId,int version,List<Guest> guests,SpecialRequest request,Scenario scenario,String key,String fingerprint,UUID correlation){return tx.execute(t->{UUID id=UUID.randomUUID(),command=UUID.randomUUID();if(!claim(owner,"BOOK",key,fingerprint,id,command))return booking(owner,replay(owner,"BOOK",key,fingerprint).orElseThrow());jdbc.sql("select id from stay_quote where id=:id and customer_id=:owner for update").param("id",quoteId).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);unbound(quoteId);var q=quote(owner,quoteId);if(q.quote().version()!=version)throw new DomainFailure(QUOTE_VERSION_CONFLICT,"Hotel quote version changed.");if(q.acceptedAt()==null)throw new DomainFailure(QUOTE_NOT_ACCEPTED,"Accept this hotel quote first.");if(q.bookingId()!=null)throw new DomainFailure(BOOKING_CONFLICT,"This quote already has a hotel booking. Open My hotel trips to recover it.");unbound(quoteId);useQuote(quoteId,id);var b=Booking.create(id,q.quote(),q.acceptedAt(),guests,request,scenario,command,correlation,clock.instant());jdbc.sql("insert into stay_booking(id,quote_id,customer_id,version,created_at,updated_at,status,payload) values(:id,:quote,:owner,1,:created,:updated,:status,cast(:payload as jsonb))").param("id",id).param("quote",quoteId).param("owner",owner).param("created",Timestamp.from(b.createdAt())).param("updated",Timestamp.from(b.updatedAt())).param("status",b.status().name()).param("payload",json.writeValueAsString(b)).update();jdbc.sql("insert into stay_work(booking_id,state) values(:id,'READY')").param("id",id).update();bookingEvent(b,"HotelBookingCreated");return b;});}
 public Booking booking(UUID owner,UUID id){return jdbc.sql("select payload::text from stay_booking where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(s->readBooking(s)).orElseThrow(this::missing);}
 private Booking lockBooking(UUID owner,UUID id){jdbc.sql("select id from stay_booking where id=:id and customer_id=:owner for update").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);return booking(owner,id);}
 public Page list(UUID owner,UUID after){Instant at=Instant.MAX;UUID cursor=new UUID(-1,-1);if(after!=null){var b=booking(owner,after);at=b.createdAt();cursor=b.id();}var sql=after==null?"select payload::text from stay_booking where customer_id=:owner order by created_at desc,id desc limit 21":"select payload::text from stay_booking where customer_id=:owner and (created_at,id)<(:at,:cursor) order by created_at desc,id desc limit 21";var query=jdbc.sql(sql).param("owner",owner);if(after!=null)query.param("at",Timestamp.from(at)).param("cursor",cursor);var list=query.query(String.class).list().stream().map(s->readBooking(s)).toList();return new Page(list.stream().limit(20).toList(),list.size()>20?list.get(19).id():null);}
 private CancellationQuote readCancellationQuote(UUID owner,UUID id){return jdbc.sql("select payload::text from stay_cancellation_quote where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(s->json.readValue(s,CancellationQuote.class)).orElseThrow(this::missing);}
 public CancellationQuote cancellationQuote(UUID owner,UUID id,String key,UUID correlation){return tx.execute(t->{UUID qid=UUID.randomUUID(),command=UUID.randomUUID();if(!claim(owner,"CANCEL_QUOTE",key,id.toString(),qid,command))return readCancellationQuote(owner,replay(owner,"CANCEL_QUOTE",key,id.toString()).orElseThrow());var b=lockBooking(owner,id);var q=b.cancellationQuote(qid,clock.instant());jdbc.sql("insert into stay_cancellation_quote(id,booking_id,customer_id,payload) values(:id,:booking,:owner,cast(:payload as jsonb))").param("id",qid).param("booking",id).param("owner",owner).param("payload",json.writeValueAsString(q)).update();return q;});}
 public Booking cancel(UUID owner,UUID id,UUID quoteId,boolean delay,boolean loss,String key,String fingerprint,UUID correlation){return tx.execute(t->{UUID command=UUID.randomUUID();if(!claim(owner,"CANCEL",key,fingerprint,id,command))return booking(owner,replay(owner,"CANCEL",key,fingerprint).orElseThrow());lockWork(owner,id);var b=lockBooking(owner,id);var q=readCancellationQuote(owner,quoteId);if(!q.bookingId().equals(id))throw new DomainFailure(BOOKING_CONFLICT,"Cancellation quote belongs to another stay.");var next=b.cancel(new Cancellation(q,delay,loss,command),clock.instant());saveBooking(next,b.version());jdbc.sql("update stay_work set state='READY',attempts=0,next_at=clock_timestamp(),lease_token=null,lease_until=null where booking_id=:id").param("id",id).update();bookingEvent(next,"HotelCancellationRequested");return next;});}
 public Booking amend(UUID owner,UUID id,UUID quoteId,long version,boolean loss,String key,String fingerprint,UUID correlation){return tx.execute(t->{UUID command=UUID.randomUUID();if(!claim(owner,"AMEND",key,fingerprint,id,command))return booking(owner,replay(owner,"AMEND",key,fingerprint).orElseThrow());lockWork(owner,id);var b=lockBooking(owner,id);jdbc.sql("select id from stay_quote where id=:id and customer_id=:owner for update").param("id",quoteId).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);var q=quote(owner,quoteId);if(q.acceptedAt()==null)throw new DomainFailure(QUOTE_NOT_ACCEPTED,"Accept the replacement hotel quote first.");if(q.bookingId()!=null)throw new DomainFailure(BOOKING_CONFLICT,"Replacement quote is already in use.");unbound(quoteId);var next=b.amend(q.quote(),version,loss,command,clock.instant());useQuote(quoteId,id);saveBooking(next,b.version());jdbc.sql("update stay_work set state='READY',attempts=0,next_at=clock_timestamp(),lease_token=null,lease_until=null where booking_id=:id").param("id",id).update();event(id,next.version(),"HotelAmendmentRequested",command,correlation,next.status().name(),next.payment().name(),next.reservation().name(),next.refund().name());return next;});}
 private void unbound(UUID quote){if(jdbc.sql("select count(*) from stay_change_quote where quote_id=:id").param("id",quote).query(Integer.class).single()!=0)throw new DomainFailure(BOOKING_CONFLICT,"This quote is bound to a specific hotel change.");}
 public ChangeQuote changeQuote(UUID owner,UUID booking,UUID id){var details=quote(owner,id);long version=jdbc.sql("select booking_version from stay_change_quote where quote_id=:id and booking_id=:booking").param("id",id).param("booking",booking).query(Long.class).optional().orElseThrow(this::missing);return new ChangeQuote(details,version);}
 public ChangeQuote createChangeQuote(UUID owner,UUID booking,long version,Quote q,String key,String fingerprint,UUID correlation){return tx.execute(t->{lockWork(owner,booking);var previous=replay(owner,"QUOTE",key,fingerprint);if(previous.isPresent())return changeQuote(owner,booking,previous.get());lockBooking(owner,booking).changeAllowed(version,clock.instant());var saved=createQuote(q,key,fingerprint,correlation);jdbc.sql("insert into stay_change_quote(quote_id,booking_id,booking_version) values(:quote,:booking,:version) on conflict(quote_id) do nothing").param("quote",saved.id()).param("booking",booking).param("version",version).update();return changeQuote(owner,booking,saved.id());});}
 public Booking change(UUID owner,UUID id,UUID quoteId,long version,List<Guest> guests,Scenario scenario,boolean delay,boolean loss,String key,String fingerprint,UUID correlation){return tx.execute(t->{UUID command=UUID.randomUUID();if(!claim(owner,"CHANGE",key,fingerprint,id,command))return booking(owner,replay(owner,"CHANGE",key,fingerprint).orElseThrow());lockWork(owner,id);var b=lockBooking(owner,id);jdbc.sql("select id from stay_quote where id=:id and customer_id=:owner for update").param("id",quoteId).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);var bound=changeQuote(owner,id,quoteId);var q=bound.details();if(bound.bookingVersion()!=version)throw new DomainFailure(BOOKING_CONFLICT,"Replacement quote belongs to a different booking version.");if(q.acceptedAt()==null)throw new DomainFailure(QUOTE_NOT_ACCEPTED,"Accept replacement terms first.");var next=b.requestChange(q.quote(),q.acceptedAt(),guests,version,scenario,delay,loss,command,clock.instant());useQuote(quoteId,id);saveBooking(next,b.version());jdbc.sql("update stay_work set state='READY',attempts=0,next_at=clock_timestamp(),lease_token=null,lease_until=null where booking_id=:id").param("id",id).update();event(id,next.version(),"HotelChangeRequested",command,correlation,next.status().name(),next.payment().name(),next.reservation().name(),next.refund().name());return next;});}
 private void saveBooking(Booking b,long expected){if(jdbc.sql("update stay_booking set version=:version,updated_at=:now,status=:status,payload=cast(:payload as jsonb) where id=:id and version=:previous").param("version",b.version()).param("now",Timestamp.from(b.updatedAt())).param("status",b.status().name()).param("payload",json.writeValueAsString(b)).param("id",b.id()).param("previous",expected).update()!=1)throw new DomainFailure(BOOKING_CONFLICT,"Concurrent hotel update; reload status.");}
 public Optional<Claim> claim(){return tx.execute(t->{var id=jdbc.sql("select booking_id from stay_work where state in('READY','RUNNING') and next_at<=clock_timestamp() and (lease_until is null or lease_until<clock_timestamp()) order by next_at,booking_id for update skip locked limit 1").query(UUID.class).optional();if(id.isEmpty())return Optional.empty();UUID token=UUID.randomUUID();int attempts=jdbc.sql("update stay_work set state='RUNNING',attempts=attempts+1,lease_token=:token,lease_until=clock_timestamp()+interval '15 seconds' where booking_id=:id returning attempts").param("token",token).param("id",id.get()).query(Integer.class).single();Booking b=readBooking(jdbc.sql("select payload::text from stay_booking where id=:id").param("id",id.get()).query(String.class).single());return Optional.of(new Claim(b,token,attempts));});}
 private boolean owns(Claim c){return jdbc.sql("select booking_id from stay_work where booking_id=:id and state='RUNNING' and lease_token=:token and lease_until>clock_timestamp() for update").param("id",c.booking().id()).param("token",c.token()).query(UUID.class).optional().isPresent();}
 public boolean complete(Claim c,Booking next){return tx.execute(t->{if(!owns(c))return false;var current=lockBooking(next.quote().owner(),next.id());if(current.version()!=c.booking().version())return false;if(next.step()==Step.REVIEW)jdbc.sql("insert into stay_review_checkpoint(booking_id,review_version,payload) values(:id,:version,cast(:payload as jsonb))").param("id",next.id()).param("version",next.version()).param("payload",json.writeValueAsString(current)).update();saveBooking(next,current.version());jdbc.sql("update stay_work set state=:state,attempts=0,next_at=clock_timestamp(),lease_token=null,lease_until=null where booking_id=:id").param("state",next.step()==Step.REVIEW?"REVIEW":next.terminal()?"DONE":"READY").param("id",next.id()).update();bookingEvent(next,c.booking().step().name().startsWith("CHANGE_")?(next.status()==Status.REVIEW?"HotelChangeReviewRequired":next.terminal()?"HotelChangeCompleted":"HotelChangeProgressed"):c.booking().step()==Step.AMEND&&next.terminal()&&next.status()!=Status.REVIEW?(next.failureCode()==null?"HotelAmendmentApplied":"HotelAmendmentRejected"):next.status()==Status.CONFIRMED?"HotelBookingConfirmed":next.refund()==Refund.SUCCEEDED?"HotelRefundCompleted":next.status()==Status.CANCELLED?"HotelBookingCancelled":next.status()==Status.FAILED?"HotelBookingFailed":next.status()==Status.REVIEW?"HotelReconciliationRequired":"HotelWorkflowProgressed");return true;});}
 public void retry(Claim c){int limit=(c.booking().step()==Step.REFUND_STATUS||c.booking().step()==Step.CHANGE_REFUND_STATUS)?20:5;if(c.attempts()>=limit){complete(c,c.booking().review(clock.instant()));return;}tx.executeWithoutResult(t->{if(!owns(c))return;jdbc.sql("update stay_work set state='READY',lease_token=null,lease_until=null,next_at=clock_timestamp()+(:delay*interval '1 millisecond') where booking_id=:id").param("id",c.booking().id()).param("delay",Math.min(8000,c.attempts()*2000)+Math.floorMod(c.booking().id().hashCode(),500)).update();});}
 private void bookingEvent(Booking b,String type){event(b.id(),b.version(),type,b.cancellation()!=null?b.cancellation().commandId():!b.changes().isEmpty()?b.change().id():b.step()==Step.AMEND||!b.amendments().isEmpty()&&b.cancellation()==null?b.amendments().getLast().id():b.cancellation()==null?b.commandId():b.cancellation().commandId(),b.correlationId(),b.status().name(),b.payment().name(),b.reservation().name(),b.refund().name());}
 private void event(UUID aggregate,long version,String type,UUID cause,UUID correlation,String status,String payment,String reservation,String refund){UUID id=UUID.randomUUID();var payload=Map.of("status",status,"payment",payment,"reservation",reservation,"refund",refund);var body=new LinkedHashMap<String,Object>();body.put("eventId",id);body.put("aggregateId",aggregate);body.put("aggregateVersion",version);body.put("eventType",type);body.put("schemaVersion",1);body.put("producer","stays");body.put("mode","MOCK");body.put("occurredAt",clock.instant());body.put("correlationId",correlation);body.put("causationId",cause);body.put("payload",payload);jdbc.sql("insert into stay_outbox(id,aggregate_id,aggregate_version,event_type,envelope) values(:id,:aggregate,:version,:type,cast(:payload as jsonb))").param("id",id).param("aggregate",aggregate).param("version",version).param("type",type).param("payload",json.writeValueAsString(body)).update();}
 public List<Event> timeline(UUID owner,UUID id){booking(owner,id);return jdbc.sql("select envelope::text from stay_outbox where aggregate_id=:id order by aggregate_version limit 50").param("id",id).query(String.class).list().stream().map(s->{var n=json.readTree(s);var p=n.get("payload");return new Event(UUID.fromString(n.get("eventId").asString()),n.get("eventType").asString(),n.get("aggregateVersion").asLong(),Instant.parse(n.get("occurredAt").asString()),p.get("status").asString(),p.get("payment").asString(),p.get("reservation").asString(),p.get("refund").asString());}).toList();}
 public Voucher readVoucher(UUID owner,UUID id){return tx.execute(t->{var b=lockBooking(owner,id);b.voucherAllowed();return voucherRecord(id,b.documentRevision()).orElseThrow(this::missing);});}
 private Optional<Voucher> voucherRecord(UUID id,UUID revision){return jdbc.sql("select payload::text from stay_voucher where booking_id=:id and revision=:revision").param("id",id).param("revision",revision).query(String.class).optional().map(s->json.readValue(s,Voucher.class));}
 public Voucher voucher(UUID owner,UUID id,String key,UUID correlation){return tx.execute(t->{var b=lockBooking(owner,id);b.voucherAllowed();UUID command=UUID.randomUUID();String fingerprint=b.modern()?fingerprint(id+":"+b.documentRevision()):id.toString();if(!claim(owner,"VOUCHER",key,fingerprint,id,command)){replay(owner,"VOUCHER",key,fingerprint).orElseThrow();return voucherRecord(id,b.documentRevision()).orElseThrow();}var prior=voucherRecord(id,b.documentRevision());if(prior.isPresent())return prior.get();var text=new StringBuilder("TRAVBOOK MOCK ACCOMMODATION VOUCHER\nNOT VALID FOR CHECK-IN. NO REAL RESERVATION OR PAYMENT.\n");text.append("Booking: ").append(id).append("\nSupplier reference: ").append(b.supplierReference()).append("\nProperty: ").append(b.currentQuote().selection().property().name()).append("\nAddress: ").append(b.currentQuote().selection().property().address()).append("\nCheck-in: ").append(b.currentQuote().selection().criteria().checkIn()).append(' ').append(b.currentQuote().selection().property().checkInTime()).append("\nCheck-out: ").append(b.currentQuote().selection().criteria().checkOut()).append(' ').append(b.currentQuote().selection().property().checkOutTime()).append("\nTimezone: ").append(b.currentQuote().selection().property().timezone()).append("\n");for(var room:b.currentQuote().selection().offers())text.append("Room ").append(room.roomIndex()+1).append(": ").append(room.roomType()).append(" / ").append(room.planCode()).append(" / ").append(room.mealPlan()).append("\n").append(room.cancellationPolicy()).append("\n");for(var guest:b.currentGuests())text.append("Guest room ").append(guest.roomIndex()+1).append(": ").append(guest.givenName()).append(' ').append(guest.familyName()).append("\n");text.append(b.deferred()?"Payment: DEFERRED. No platform collection. Due at property INR ":"Payment: simulated platform capture. Total INR ").append(b.currentQuote().selection().total().amount().toPlainString()).append("\nSpecial request: ").append(b.specialRequest()).append(" (not guaranteed)\n");byte[] bytes=text.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>32768)throw new IllegalStateException("Voucher size exceeded");String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException(e);}var v=new Voucher(UUID.randomUUID(),id,clock.instant(),hash,bytes.length,text.toString());jdbc.sql("insert into stay_voucher(id,booking_id,revision,payload) values(:id,:booking,:revision,cast(:payload as jsonb))").param("id",v.id()).param("booking",id).param("revision",b.documentRevision()).param("payload",json.writeValueAsString(v)).update();event(v.id(),1,"HotelVoucherCreated",command,correlation,"CREATED","N/A","N/A","N/A");return v;});}

 public java.util.List<com.travbook.shared.domain.Recovery.Case> reviews(int page){return jdbc.sql("select id from stay_booking where status='REVIEW' order by updated_at,id limit 20 offset :offset").param("offset",page*20).query(UUID.class).list().stream().map(this::review).toList();}
 private Booking reviewBooking(UUID id){return jdbc.sql("select payload::text from stay_booking where id=:id").param("id",id).query(String.class).optional().map(p->readBooking(p)).orElseThrow(this::missing);}
 public com.travbook.shared.domain.Recovery.Case review(UUID id){var b=reviewBooking(id);var actions=jdbc.sql("select payload::text from stay_recovery_action where booking_id=:id order by created_at,id limit 3").param("id",id).query(String.class).list().stream().map(p->json.readValue(p,com.travbook.shared.domain.Recovery.Action.class)).toList();boolean available=b.status()==Status.REVIEW&&actions.size()<3&&jdbc.sql("select count(*) from stay_review_checkpoint where booking_id=:id and review_version=:version").param("id",id).param("version",b.version()).query(Integer.class).single()==1;return new com.travbook.shared.domain.Recovery.Case(id,b.version(),b.status().name(),b.payment().name(),b.reservation().name(),b.refund().name(),available?checkpoint(id,b.version()).step().name():b.step().name(),available,b.updatedAt(),actions);}
 public Booking checkpoint(UUID id,long version){return jdbc.sql("select payload::text from stay_review_checkpoint where booking_id=:id and review_version=:version").param("id",id).param("version",version).query(String.class).optional().map(p->readBooking(p)).orElseThrow(()->new DomainFailure(BOOKING_CONFLICT,"No saved recovery checkpoint; legacy review requires investigation."));}
 public Optional<com.travbook.shared.domain.Recovery.Action> recoveryReplay(String actor,String key,String fingerprint){return jdbc.sql("select fingerprint,payload::text from stay_recovery_action where actor=:actor and command_key=:key").param("actor",actor).param("key",key).query((r,n)->{if(!r.getString(1).equals(fingerprint))throw new DomainFailure(IDEMPOTENCY_CONFLICT,"Recovery key was used for different inputs.");return json.readValue(r.getString(2),com.travbook.shared.domain.Recovery.Action.class);}).optional();}
 public com.travbook.shared.domain.Recovery.Action resume(UUID id,long version,String actor,com.travbook.shared.domain.Recovery.Reason reason,String key,String fingerprint,UUID correlation){return tx.execute(t->{jdbc.sql("select pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","stay-recovery:"+actor+":"+key).query((r,n)->true).single();var replay=recoveryReplay(actor,key,fingerprint);if(replay.isPresent())return replay.get();jdbc.sql("select booking_id from stay_work where booking_id=:id for update").param("id",id).query(UUID.class).optional().orElseThrow(this::missing);var original=reviewBooking(id);var current=lockBooking(original.quote().owner(),id);if(current.status()!=Status.REVIEW||current.version()!=version||!review(id).recoverable())throw new DomainFailure(BOOKING_CONFLICT,"Review changed, lacks a checkpoint, or exhausted its three recovery attempts.");var next=current.resumeFrom(checkpoint(id,version),clock.instant());var action=new com.travbook.shared.domain.Recovery.Action(UUID.randomUUID(),id,next.version(),actor,reason,clock.instant());jdbc.sql("insert into stay_recovery_action(id,booking_id,actor,command_key,fingerprint,created_at,payload) values(:id,:booking,:actor,:key,:fingerprint,:at,cast(:payload as jsonb))").param("id",action.id()).param("booking",id).param("actor",actor).param("key",key).param("fingerprint",fingerprint).param("at",Timestamp.from(action.createdAt())).param("payload",json.writeValueAsString(action)).update();saveBooking(next,current.version());jdbc.sql("update stay_work set state='READY',attempts=0,next_at=clock_timestamp(),lease_token=null,lease_until=null where booking_id=:id").param("id",id).update();event(id,next.version(),"HotelReconciliationResumed",action.id(),correlation,next.status().name(),next.payment().name(),next.reservation().name(),next.refund().name());return action;});}

 public Booking legacyReview(UUID id,long version){var b=reviewBooking(id);if(b.status()!=Status.REVIEW||b.version()!=version||review(id).actions().size()>=3||jdbc.sql("select count(*) from stay_review_checkpoint where booking_id=:id and review_version=:version").param("id",id).param("version",version).query(Integer.class).single()!=0)throw new DomainFailure(BOOKING_CONFLICT,"Use saved checkpoint recovery, or refresh the current review.");return b;}
 public com.travbook.shared.domain.Recovery.Action reconcileLegacy(UUID id,long version,String actor,com.travbook.shared.domain.Recovery.Reason reason,String key,String fingerprint,UUID correlation,com.travbook.shared.domain.Recovery.Proof proof){return tx.execute(t->{jdbc.sql("select pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","stay-recovery:"+actor+":"+key).query((r,n)->true).single();var replay=recoveryReplay(actor,key,fingerprint);if(replay.isPresent())return replay.get();jdbc.sql("select booking_id from stay_work where booking_id=:id for update").param("id",id).query(UUID.class).optional().orElseThrow(this::missing);var original=reviewBooking(id);lockBooking(original.quote().owner(),id);var current=legacyReview(id,version);var next=current.reconcileLegacy(proof,clock.instant());var action=new com.travbook.shared.domain.Recovery.Action(UUID.randomUUID(),id,next.version(),actor,reason,clock.instant());jdbc.sql("insert into stay_recovery_action(id,booking_id,actor,command_key,fingerprint,created_at,payload) values(:id,:booking,:actor,:key,:fingerprint,:at,cast(:payload as jsonb))").param("id",action.id()).param("booking",id).param("actor",actor).param("key",key).param("fingerprint",fingerprint).param("at",Timestamp.from(action.createdAt())).param("payload",json.writeValueAsString(action)).update();jdbc.sql("insert into stay_legacy_proof(action_id,booking_id,prior_version,proof) values(:action,:booking,:version,cast(:proof as jsonb))").param("action",action.id()).param("booking",id).param("version",version).param("proof",json.writeValueAsString(proof)).update();saveBooking(next,version);jdbc.sql("update stay_work set state='DONE',attempts=0,lease_token=null,lease_until=null where booking_id=:id").param("id",id).update();event(id,next.version(),"HotelLegacyOutcomeReconciled",action.id(),correlation,next.status().name(),next.payment().name(),next.reservation().name(),next.refund().name());return action;});}
}
